smart.css:
.smc-root {
  color: var(--smc-text);
  font-family: var(--smc-font-body);
  font-size: 17px;
  line-height: 1.72;
}

.smc-root h2,
.smc-root h3 {
  color: var(--smc-primary);
  font-family: var(--smc-font-heading);
  line-height: 1.3;
}

.smc-root h2 {
  border-top: 1px solid var(--smc-border);
  font-size: 26px;
  margin-top: 38px;
  padding-top: 28px;
}

.smc-root h3 {
  font-size: 20px;
  margin-top: 20px;
}

.smc-root p {
  margin-top: 14px;
}

.smc-section ul {
  margin: 14px 0 0;
  padding-left: 20px;
  display: grid;
  gap: 10px;
}

.smc-section li {
  line-height: 1.68;
}

.smc-root em {
  font-style: italic;
}

.smc-root strong {
  font-weight: 700;
  color: var(--smc-primary);
}

.smc-root a {
  color: var(--smc-accent);
  font-weight: 600;
  text-decoration: underline;
  text-underline-offset: 3px;
}

.smc-root a:hover {
  color: var(--smc-primary);
}

.smc-intro {
  display: grid;
  grid-template-columns: minmax(0, 1fr);
  gap: 24px;
  padding: 24px;
  background: var(--smc-surface);
  border: 1px solid var(--smc-border);
  border-radius: var(--smc-radius);
  margin-bottom: 24px;
}

.smc-eyebrow {
  font-size: 13px;
  font-weight: 800;
  letter-spacing: .08em;
  text-transform: uppercase;
  color: var(--smc-accent);
  margin: 0 0 8px;
}

.smc-intro-copy h2 {
  border-top: 0;
  font-size: 28px;
  margin-top: 0;
  padding-top: 0;
  line-height: 1.25;
}

.smc-intro-media {
  margin: 0;
  text-align: center;
}

.smc-intro-media img {
  display: block;
  width: 100%;
  height: auto;
  border-radius: var(--smc-radius);
  object-fit: cover;
  border: 1px solid var(--smc-border);
}

.smc-intro-media figcaption,
.smc-lifestyle figcaption,
.smc-detail-media figcaption {
  color: var(--smc-muted);
  font-size: 13.5px;
  line-height: 1.5;
  margin-top: 10px;
  font-style: italic;
  text-align: center;
}

.smc-entity-box {
  background: color-mix(in srgb, var(--smc-primary) 5%, var(--smc-bg));
  border: 1.5px solid color-mix(in srgb, var(--smc-primary) 22%, var(--smc-border));
  border-radius: var(--smc-radius);
  padding: 22px 20px;
  margin: 24px 0 32px;
}

.smc-entity-title {
  font-size: 14px;
  font-weight: 800;
  letter-spacing: .06em;
  text-transform: uppercase;
  color: var(--smc-primary);
  margin: 0 0 14px;
}

.smc-entity-grid {
  display: grid;
  grid-template-columns: minmax(0, 1fr);
  gap: 12px;
}

.smc-entity-item {
  background: var(--smc-bg);
  border: 1px solid var(--smc-border);
  border-radius: var(--smc-radius);
  padding: 12px 14px;
}

.smc-entity-label {
  display: block;
  font-size: 12.5px;
  font-weight: 700;
  text-transform: uppercase;
  letter-spacing: .04em;
  color: var(--smc-muted);
  margin-bottom: 4px;
}

.smc-entity-val {
  display: block;
  font-size: 15px;
  font-weight: 600;
  color: var(--smc-text);
  line-height: 1.45;
}

.smc-feature-grid {
  display: grid;
  grid-template-columns: minmax(0, 1fr);
  gap: 18px;
  margin-top: 22px;
}

.smc-feature-card {
  position: relative;
  background: var(--smc-bg);
  border: 1px solid var(--smc-border);
  border-radius: var(--smc-radius);
  padding: 22px 20px 20px;
  box-shadow: 0 2px 8px rgba(0, 0, 0, 0.03);
}

.smc-card-badge {
  display: inline-block;
  font-size: 13px;
  font-weight: 800;
  color: var(--smc-accent);
  background: color-mix(in srgb, var(--smc-accent) 12%, var(--smc-bg));
  border: 1px solid color-mix(in srgb, var(--smc-accent) 25%, var(--smc-border));
  padding: 3px 10px;
  border-radius: 999px;
  margin-bottom: 8px;
}

.smc-feature-card h3 {
  margin-top: 4px;
  font-size: 19px;
}

.smc-feature-card p {
  color: var(--smc-muted);
  font-size: 15.5px;
  line-height: 1.6;
  margin-top: 8px;
}

.smc-table-wrap {
  overflow-x: auto;
  margin-top: 20px;
  border: 1px solid var(--smc-border);
  border-radius: var(--smc-radius);
}

.smc-compare-table {
  width: 100%;
  border-collapse: collapse;
  min-width: 600px;
  font-size: 15px;
  background: var(--smc-bg);
}

.smc-compare-table th {
  background: var(--smc-primary);
  color: var(--smc-bg);
  padding: 14px 16px;
  text-align: left;
  font-weight: 700;
}

.smc-compare-table td {
  padding: 14px 16px;
  border-bottom: 1px solid var(--smc-border);
  vertical-align: top;
  line-height: 1.55;
}

.smc-compare-table tr:last-child td {
  border-bottom: 0;
}

.smc-detail-grid {
  display: grid;
  grid-template-columns: minmax(0, 1fr);
  gap: 24px;
  margin-top: 18px;
  align-items: center;
}

.smc-detail-media {
  margin: 0;
}

.smc-detail-media img {
  display: block;
  width: 100%;
  height: auto;
  border-radius: var(--smc-radius);
  border: 1px solid var(--smc-border);
}

.smc-verdict-card {
  background: color-mix(in srgb, var(--smc-accent) 6%, var(--smc-bg));
  border: 1.5px solid color-mix(in srgb, var(--smc-accent) 26%, var(--smc-border));
  border-radius: var(--smc-radius);
  padding: 24px 20px;
  margin-top: 22px;
}

.smc-verdict-lead {
  font-size: 16.5px;
  line-height: 1.65;
  margin-top: 0;
}

.smc-verdict-grid {
  display: grid;
  grid-template-columns: minmax(0, 1fr);
  gap: 16px;
  margin: 18px 0;
}

.smc-verdict-item {
  background: var(--smc-bg);
  border: 1px solid var(--smc-border);
  border-radius: var(--smc-radius);
  padding: 16px;
}

.smc-verdict-item h3 {
  font-size: 16px;
  margin: 0 0 6px;
  color: var(--smc-primary);
}

.smc-verdict-item p {
  font-size: 14.5px;
  line-height: 1.6;
  color: var(--smc-muted);
  margin: 0;
}

.smc-verdict-conclusion {
  font-size: 15.5px;
  line-height: 1.65;
  border-top: 1px dashed color-mix(in srgb, var(--smc-accent) 30%, var(--smc-border));
  padding-top: 16px;
  margin: 16px 0 0;
}

.smc-faq {
  margin-top: 40px;
}

.smc-faq-list {
  display: grid;
  gap: 12px;
  margin-top: 18px;
}

.smc-faq details {
  background: var(--smc-bg);
  border: 1px solid var(--smc-border);
  border-radius: var(--smc-radius);
  padding: 14px 18px;
  transition: border-color .2s;
}

.smc-faq details[open] {
  border-color: var(--smc-primary);
}

.smc-faq summary {
  font-size: 16.5px;
  font-weight: 700;
  color: var(--smc-primary);
  cursor: pointer;
  list-style: none;
  display: flex;
  justify-content: space-between;
  align-items: center;
}

.smc-faq summary::-webkit-details-marker {
  display: none;
}

.smc-faq summary::after {
  content: "+";
  font-size: 20px;
  font-weight: 400;
  color: var(--smc-accent);
}

.smc-faq details[open] summary::after {
  content: "−";
}

.smc-faq details p {
  font-size: 15.5px;
  line-height: 1.65;
  color: var(--smc-muted);
  margin: 12px 0 4px;
}

.smc-related {
  margin-top: 44px;
  padding: 22px;
  background: var(--smc-surface);
  border: 1px solid var(--smc-border);
  border-radius: var(--smc-radius);
}

.smc-related strong {
  display: block;
  font-size: 14px;
  text-transform: uppercase;
  letter-spacing: .06em;
  color: var(--smc-primary);
  margin-bottom: 12px;
}

.smc-related-links {
  display: flex;
  flex-wrap: wrap;
  gap: 10px 14px;
}

.smc-related-links a {
  display: inline-block;
  padding: 6px 14px;
  background: var(--smc-bg);
  border: 1px solid var(--smc-border);
  border-radius: 999px;
  text-decoration: none;
  font-size: 14px;
}

.smc-related-links a:hover {
  border-color: var(--smc-primary);
  color: var(--smc-primary);
}

@container smc (min-width: 700px) {
  .smc-intro {
    grid-template-columns: 1.1fr .9fr;
    align-items: center;
    padding: 32px;
  }
  .smc-entity-grid {
    grid-template-columns: repeat(2, minmax(0, 1fr));
  }
  .smc-feature-grid {
    grid-template-columns: repeat(2, minmax(0, 1fr));
  }
  .smc-detail-grid {
    grid-template-columns: 1.05fr .95fr;
  }
  .smc-verdict-grid {
    grid-template-columns: repeat(3, minmax(0, 1fr));
  }
}

